head.script:
/* =========================================================================
 * WAEA-885 검증용 _fix 샘플
 * 이슈: getMergedInfo() 호출 시 "병합 시작(좌상단) 셀"에서
 *       endRowIndex, endColIndex 가 반환되지 않는 문제 (내부 셀은 정상)
 *
 * 데이터 상 병합 구조:
 *   - col1(0열): row2,3,4 = "3"  → rows 2~4 병합  ⇒ (2,0)은 "병합 시작 셀" (버그 대상)
 *   - col2(1열): row0~4  = "0"  → rows 0~4 병합  ⇒ (2,1)은 "병합 내부 셀" (정상)
 *
 * 확인: 각 버튼 클릭 → 반환 객체를 로그창에 JSON 으로 표시.
 *       (원본은 alert(객체)라 [object Object]만 떠서 속성 확인 불가였음)
 * ========================================================================= */

scwin.log = function (msg, obj) {
    var line = msg + (obj !== undefined ? " " + JSON.stringify(obj) : "");
    console.log("[WAEA-885]", msg, (obj !== undefined ? obj : ""));
    try { txa_log.setValue((txa_log.getValue() || "") + line + "\n"); } catch (e) {}
};
scwin.clearLog = function () { try { txa_log.setValue(""); } catch (e) {} };

scwin.onpageload = function() {
    btn1.click();          // 데이터 로드 → 병합 생성
    scwin.log("WAEA-885 _fix 로드 완료. getinfo 버튼으로 endRowIndex/endColIndex 반환 여부 확인.");
};

scwin.btn1_onclick = function (e) {
    const rows = ib1.getValue();
    const cols = 10;
    const data = Array.from({ length: rows }, (_, r) => {
        const rowNum = r + 1;
        let rowObj = {};
        rowObj['col1'] = String(Math.min((r % 5) + 1, 3));
        rowObj['depthcol'] = String(Math.min((r % 5) + 1, 3));
        rowObj['col2'] = Math.trunc(r / 5).toString();
        rowObj['col3'] = 1;
        rowObj['col4'] = r * 100;
        rowObj['col5'] = "/cm/images/base/ico_upload.svg";
        for (let c = 6; c <= cols; c++) { rowObj[`col${c}`] = `row${rowNum}_col${c}`; }
        return rowObj;
    });
    dl1.setJSON(data, false);
    dl2.setJSON(data, false);
};

// 공통: getMergedInfo 호출 + end 좌표 포함 여부 자동 판정
scwin.callGetMergedInfo = function (rowIndex, colIndex, note) {
    var info = gv2.getMergedInfo(rowIndex, colIndex);
    scwin.log("getMergedInfo(" + rowIndex + "," + colIndex + ") [" + note + "] =", info);
    if (info && info.merged) {
        var hasEnd = (info.endRowIndex !== undefined && info.endColIndex !== undefined);
        scwin.log("   → endRowIndex=" + info.endRowIndex + ", endColIndex=" + info.endColIndex
            + "  ⇒ " + (hasEnd ? "PASS (end 좌표 정상)" : "FAIL (end 좌표 누락 = 버그)"));
    } else {
        scwin.log("   → merged=false 또는 null (병합 아님)");
    }
    return info;
};

// 이슈 재현 1) 병합 시작(좌상단) 셀 (2,0) → 수정 전 end 좌표 undefined = 버그
scwin.getinfo_2_0 = function () { scwin.callGetMergedInfo(2, 0, "병합 시작셀"); };
// 이슈 재현 2) 병합 내부 셀 (2,1) → 항상 정상
scwin.getinfo_2_1 = function () { scwin.callGetMergedInfo(2, 1, "병합 내부셀"); };
// 일반(병합 아님) 셀 확인 (3열은 매행 r*100 으로 값 달라 병합 없음)
scwin.getinfo_plain = function () { scwin.callGetMergedInfo(2, 3, "일반셀"); };
// 사용자 지정 좌표
scwin.getinfo_custom = function () {
    scwin.callGetMergedInfo(parseInt(ibRow.getValue(), 10), parseInt(ibCol.getValue(), 10), "사용자지정");
};
